const entrada = $('HTTP Request').first().json;
const csv = entrada.data ?? entrada.body ?? entrada.text;

if (typeof csv !== 'string' || !csv.trim()) {
  throw new Error('CSV não encontrado na saída HTTP');
}

function parseCSV(s) {
  const rows = [];
  let row = [], field = '', quoted = false;

  for (let i = 0; i < s.length; i++) {
    const c = s[i];

    if (c === '"') {
      if (quoted && s[i + 1] === '"') {
        field += '"';
        i++;
      } else {
        quoted = !quoted;
      }
    } else if (c === ',' && !quoted) {
      row.push(field);
      field = '';
    } else if ((c === '\n' || c === '\r') && !quoted) {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(field);
      if (row.some(x => x.trim())) rows.push(row);
      row = [];
      field = '';
    } else {
      field += c;
    }
  }

  if (quoted) throw new Error('CSV com aspas não fechadas');

  row.push(field);
  if (row.some(x => x.trim())) rows.push(row);
  return rows;
}

const rows = parseCSV(csv.replace(/^\uFEFF/, ''));

if (rows.length < 2) throw new Error('CSV sem dados');

const header = rows.shift().map(x => x.trim().toLowerCase());

for (const col of ['perfil', 'produto', 'minimo', 'rentabilidade']) {
  if (!header.includes(col)) {
    throw new Error('Coluna ausente: ' + col);
  }
}

return rows.map((r, n) => {
  if (r.length !== header.length) {
    throw new Error('Quantidade de colunas inválida na linha ' + (n + 2));
  }

  const obj = Object.fromEntries(
    header.map((k, i) => [k, r[i].trim()])
  );

  const raw = obj.minimo.replace(/R\$|\s/g, '');

  obj.minimo = Number(
    raw.includes(',')
      ? raw.replace(/\./g, '').replace(',', '.')
      : raw
  );

  if (!Number.isFinite(obj.minimo) || obj.minimo < 0) {
    throw new Error('Mínimo inválido na linha ' + (n + 2));
  }

  return { json: obj };
});

const clientes = $('Webhook').first().json.body?.clientes;
const investimentos = $('Normalizar investimentos').all().map(x => x.json);

if (!Array.isArray(clientes)) {
  throw new Error('Webhook: body.clientes deve ser uma lista');
}

const normalizar = x => String(x ?? '')
  .trim()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const dinheiro = x => {
  if (typeof x === 'number') return x;
  const s = String(x ?? '').replace(/R\$|\s/g, '');
  return Number(
    s.includes(',')
      ? s.replace(/\./g, '').replace(',', '.')
      : s
  );
};

const resultados = clientes.map(cliente => {
  const saldo = dinheiro(cliente.saldo);

  if (!Number.isFinite(saldo) || saldo < 0) {
    return {
      json: {
        ...cliente,
        status: 'dados_invalidos',
        motivo: 'Saldo inválido'
      }
    };
  }

  const elegiveis = investimentos.filter(i =>
    normalizar(i.perfil) === normalizar(cliente.perfil) &&
    Number.isFinite(dinheiro(i.minimo)) &&
    dinheiro(i.minimo) >= 0 &&
    dinheiro(i.minimo) <= saldo
  );

  if (!elegiveis.length) {
    return {
      json: {
        ...cliente,
        status: 'sem_opcao',
        motivo: 'Nenhum produto compatível com perfil e saldo'
      }
    };
  }

  const escolhido = [...elegiveis].sort((a, b) =>
    dinheiro(a.minimo) - dinheiro(b.minimo) ||
    String(a.produto).localeCompare(String(b.produto), 'pt-BR')
  )[0];

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      produto: escolhido.produto,
      rentabilidade: escolhido.rentabilidade,
      investimento_minimo: dinheiro(escolhido.minimo),
      status: 'elegivel',
      mensagem_estatica:
        `Olá, ${cliente.nome}. Identificamos o produto ${escolhido.produto} ` +
        `como uma possibilidade para análise, considerando o perfil ` +
        `${cliente.perfil} e o valor mínimo de aplicação. ` +
        `A rentabilidade informada é ${escolhido.rentabilidade}; ` +
        `não há garantia de resultados futuros. ` +
        `Antes de investir, confira riscos, liquidez e condições.`
    }
  };
});

return resultados;

