const respostas = $input.all();

const clientes = $('Selecionar investimentos').all();

if (respostas.length !== clientes.length) {
  throw new Error(
    `Quantidade incompatível: ${respostas.length} respostas ` +
    `para ${clientes.length} clientes.`
  );
}

const resultados = respostas.map((item, index) => {
  const cliente = clientes[index].json;

  const mensagem =
    item.json.output?.[0]?.content?.find(
      parte => parte.type === 'output_text'
    )?.text;

  if (typeof mensagem !== 'string' || !mensagem.trim()) {
    throw new Error(
      `Mensagem ausente para o cliente na posição ${index + 1}`
    );
  }

  const email = String(cliente.email ?? '').trim();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error(
      `E-mail inválido para o cliente na posição ${index + 1}`
    );
  }

  return {
    json: {
      nome: cliente.nome,
      email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      produto: cliente.produto,
      rentabilidade: cliente.rentabilidade,
      investimento_minimo: cliente.investimento_minimo,
      status: cliente.status,
      assunto: 'Informações sobre investimentos',
      mensagem: mensagem.trim(),
      aprovado_para_envio: false
    }
  };
});

return resultados;
